class CusPcapStart(RtgPcapStart):
    """Command for starting cus-pcap script."""

    def __init__(self, connection, ctrls, path="/opt/cus/bin/cus-pcap", options=None, prompt=None, newline_chars=None,
                 runner=None):
        """
        Cus pcap start command. Has to be run as root. Script has to be stopped using pcap stop command.

        :param connection: moler connection to device, terminal when command is executed.
        :param ctrls: List with controllers' numbers.
        :param path: Path to cus-pcap script.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(CusPcapStart, self).__init__(connection, ctrls, path=path, options=options, prompt=prompt,
                                           newline_chars=newline_chars, runner=runner)


